// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }
    function testFuzz_property(address actor, bytes32 guessHash, uint256 startBlock) public {
        vm.assume(actor != address(0));
        startBlock = bound(startBlock, 1, type(uint64).max - 2);
        vm.roll(startBlock);
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guessHash);
        vm.roll(startBlock + 1);
        vm.prank(actor);
        bool ok;
        try c.settle() { ok = true; } catch { ok = false; }
        assertTrue(!ok, "settle must not succeed in the block immediately after locking");
    }
}
